// Read Vite manifest and local emitted files only. Static graph sizes are not browser timing measurements.
import assert from 'node:assert/strict';import {readFileSync,writeFileSync} from 'node:fs';import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';
const root=new URL('../',import.meta.url),dist=new URL('apps/web/dist/',root),manifest=JSON.parse(readFileSync(new URL('.vite/manifest.json',dist),'utf8'));
function closure(starts){const visited=new Set(),files=new Set();function walk(key){if(visited.has(key))return;visited.add(key);const entry=manifest[key];assert.ok(entry,'Missing manifest entry');assert.ok(typeof entry.file==='string');files.add(entry.file);for(const css of entry.css??[])files.add(css);for(const next of entry.imports??[])walk(next);}for(const key of starts)walk(key);return [...files].sort();}
function measure(starts){const files=closure(starts).map(name=>{assert.match(name,/^assets\/[A-Za-z0-9_.-]+\.(?:js|css)$/);const bytes=readFileSync(new URL(name,dist));return {file:name,kind:name.endsWith('.js')?'javascript':'css',bytes:bytes.length,gzip_level9_bytes:gzipSync(bytes,{level:9}).length,sha256:createHash('sha256').update(bytes).digest('hex')};});const total=kind=>({bytes:files.filter(x=>x.kind===kind).reduce((n,x)=>n+x.bytes,0),gzip_level9_bytes:files.filter(x=>x.kind===kind).reduce((n,x)=>n+x.gzip_level9_bytes,0)});return {javascript:total('javascript'),css:total('css'),files};}
const result={measured_at:new Date().toISOString(),node_version:process.version,scope:'LOCAL_STATIC_IMPORT_GRAPH_NOT_NETWORK_TIMING',entry:measure(['index.html']),login_route:measure(['index.html','src/pages/LoginPage.vue']),assets_route:measure(['index.html','src/pages/AssetsPage.vue']),all_manifest_references_exist:true};
for(const key of Object.keys(manifest))closure([key]).forEach(name=>{readFileSync(new URL(name,dist));});
if(process.argv[2])writeFileSync(process.argv[2],JSON.stringify(result,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({entry:result.entry.javascript,login:result.login_route.javascript,assets:result.assets_route.javascript,all_manifest_references_exist:true}));
